def verifier(assign):
    import math
    # Validate slots
    required = ['angle', 'p', 'q', 'r', 'A', 'B', 'C']
    for k in required:
        if k not in assign:
            # Missing field
            return (False, None)
    angle = assign['angle']
    p = assign['p']
    q = assign['q']
    r = assign['r']
    A = assign['A']
    B = assign['B']
    C = assign['C']
    # Type and domain checks
    try:
        angle = int(angle)
        p = int(p)
        q = int(q)
        r = int(r)
        C = int(C)
        A = float(A)
        B = float(B)
    except Exception:
        return (False, None)
    if angle <= 0 or p <= 0 or q <= 0 or r <= 0 or C <= 0:
        return (False, None)
    if not (math.isfinite(A) and math.isfinite(B)):
        return (False, None)
    if A <= 0 or B <= 0:
        return (False, None)
    # Trig constant
    ca = math.cos(angle)
    den = 2 * ca + math.cos(3 * angle)
    if abs(den) < 1e-9:
        # Degenerate trig denominator
        return (False, None)
    K = (16 * (ca ** 5) - math.cos(5 * angle)) / den
    if not math.isfinite(K):
        return (False, None)
    # Enforce the intended trig simplification (should be exactly 5)
    if abs(K - 5.0) > 1e-7:
        # This family relies on the identity yielding a constant factor 5
        return (False, None)

    # Define ratio over u=b/a, v=c/b
    def ratio_uv(u, v):
        N = p * u + q * (u ** 3) * v + r * (u ** 2) * (v ** 2)
        D = A + B * (u ** 3) + C * (u ** 3) * (v ** 3)
        return N / D

    # Global search for maximum over u,v>0 using multi-scale grid refinement
    def grid_max():
        best_val = -1.0
        best_u = None
        best_v = None
        # coarse grid
        U_vals = [(-6 + i * 0.2) for i in range(int((6 - (-6)) / 0.2) + 1)]
        V_vals = [(-6 + j * 0.2) for j in range(int((6 - (-6)) / 0.2) + 1)]
        for U in U_vals:
            u = math.exp(U)
            for V in V_vals:
                v = math.exp(V)
                val = ratio_uv(u, v)
                if val > best_val:
                    best_val = val
                    best_u = u
                    best_v = v
        # refine around best several times
        for step in [0.1, 0.05, 0.02, 0.01]:
            U0 = math.log(best_u)
            V0 = math.log(best_v)
            local_best_val = best_val
            local_best_u = best_u
            local_best_v = best_v
            for dU in [(-4 + i) * step for i in range(9)]:
                for dV in [(-4 + j) * step for j in range(9)]:
                    u = math.exp(U0 + dU)
                    v = math.exp(V0 + dV)
                    val = ratio_uv(u, v)
                    if val > local_best_val:
                        local_best_val = val
                        local_best_u = u
                        local_best_v = v
            best_val = local_best_val
            best_u = local_best_u
            best_v = local_best_v
        return best_val, best_u, best_v

    max_val, u_star, v_star = grid_max()
    if not (math.isfinite(max_val) and max_val > 0):
        return (False, None)
    # Difficulty enforcement: ensure interior maximizer (not at extreme of search domain)
    U_star = math.log(u_star)
    V_star = math.log(v_star)
    if abs(U_star) > 5.9 or abs(V_star) > 5.9:
        # Maximizer at boundary suggests trivial or ill-posed instance
        return (False, None)
    # Ensure the problem isn't trivial (e.g., u=v=1)
    base_val = ratio_uv(1.0, 1.0)
    if max_val <= base_val * 1.02:
        return (False, None)
    # Final answer: multiply by trig constant
    answer = K * max_val
    return (True, answer)
